### Summary

With a `utls.ClientSessionCache` wired on both dials, a second TLS 1.3 handshake against the same server successfully resumes (`ConnectionState().DidResume == true`) when using `utls.HelloGolang`, but never resumes for `utls.HelloChrome_120` (a named mimicry preset) even though the handshake itself succeeds and the cache's `Get`/`Put` both fire correctly. Reproduced consistently (5/5 runs) with a minimal, dependency-free repro (attached below).

### Environment

- Tested against both:
  - `v1.7.4-0.20250521174854-63aeec73c564` (pseudo-version currently vendored by our project)
  - `v1.8.2` (latest tagged release as of 2026-07) — same result, unchanged
- Go 1.26.3, macOS (arm64)

### Repro

Minimal `main.go` (single file, only dependency is this module):

```go
// Minimal, dependency-free repro: utls.UClient resumption works for
// utls.HelloGolang but not for a named ClientHelloID that goes through
// UConn.ApplyPreset, against a local TLS 1.3 server with session tickets
// enabled and a real utls.ClientSessionCache wired on both dials.
package main

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"fmt"
	"math/big"
	"net"
	"os"
	"time"

	utls "github.com/refraction-networking/utls"
)

func main() {
	cert := generateCert()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		fatal("listen", err)
	}
	defer ln.Close()

	srvCfg := &tls.Config{Certificates: []tls.Certificate{cert}}
	go serve(ln, srvCfg)

	roots := x509.NewCertPool()
	roots.AddCert(mustParseCert(cert))

	fmt.Println("id, first_handshake_ok, first_did_resume, second_handshake_ok, second_did_resume")
	check("HelloGolang (control, no ApplyPreset)", ln.Addr().String(), roots, utls.HelloGolang)
	check("HelloChrome_120 (named preset, via ApplyPreset)", ln.Addr().String(), roots, utls.HelloChrome_120)
}

func check(label, addr string, roots *x509.CertPool, id utls.ClientHelloID) {
	cache := utls.NewLRUClientSessionCache(0)
	first, firstErr := dial(addr, roots, id, cache)
	firstResumed := false
	if firstErr == nil {
		firstResumed = first.ConnectionState().DidResume
		first.Close()
	}
	time.Sleep(150 * time.Millisecond) // let the post-handshake NewSessionTicket arrive

	second, secondErr := dial(addr, roots, id, cache)
	secondResumed := false
	if secondErr == nil {
		secondResumed = second.ConnectionState().DidResume
		second.Close()
	}
	fmt.Printf("%-45s first_ok=%-5v first_resume=%-5v second_ok=%-5v second_resume=%v\n",
		label, firstErr == nil, firstResumed, secondErr == nil, secondResumed)
}

func dial(addr string, roots *x509.CertPool, id utls.ClientHelloID, cache utls.ClientSessionCache) (*utls.UConn, error) {
	conn, err := net.DialTimeout("tcp", addr, 5*time.Second)
	if err != nil {
		return nil, err
	}
	cfg := &utls.Config{
		ServerName:                         "localhost",
		RootCAs:                            roots,
		ClientSessionCache:                 cache,
		PreferSkipResumptionOnNilExtension: true,
	}
	uconn := utls.UClient(conn, cfg, id)
	if err := uconn.Handshake(); err != nil {
		conn.Close()
		return nil, err
	}
	// The TLS 1.3 NewSessionTicket is sent post-handshake and only actually
	// read (and so cached) once the client does a Write+Read.
	if _, err := uconn.Write([]byte("x")); err != nil {
		uconn.Close()
		return nil, err
	}
	buf := make([]byte, 1)
	uconn.SetReadDeadline(time.Now().Add(3 * time.Second))
	if _, err := uconn.Read(buf); err != nil {
		uconn.Close()
		return nil, err
	}
	return uconn, nil
}

func serve(ln net.Listener, cfg *tls.Config) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		go func() {
			tlsConn := tls.Server(conn, cfg)
			defer tlsConn.Close()
			buf := make([]byte, 1)
			tlsConn.SetReadDeadline(time.Now().Add(2 * time.Second))
			if _, err := tlsConn.Read(buf); err != nil {
				return
			}
			tlsConn.Write([]byte("y"))
		}()
	}
}

func generateCert() tls.Certificate {
	key, _ := rsa.GenerateKey(rand.Reader, 2048)
	template := x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: "localhost"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
		DNSNames:     []string{"localhost"},
		KeyUsage:     x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}
	der, _ := x509.CreateCertificate(rand.Reader, &template, &template, &key.PublicKey, key)
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
}

func mustParseCert(cert tls.Certificate) *x509.Certificate {
	parsed, _ := x509.ParseCertificate(cert.Certificate[0])
	return parsed
}

func fatal(step string, err error) {
	fmt.Fprintf(os.Stderr, "%s: %v\n", step, err)
	os.Exit(1)
}
```

